// m=ます形, ba=そんけい（れる・られる）, g=group, ex=メモ(任意)
// 教科書L24-1「ぶんけい1」の表が正（Ⅱ p182: とります・読みます・作ります・そだてます・参加します・持って来ます）
// 語彙 = 教科書掲載語＋「うえの人が自分でする動作」の既習語。うけみ(L19-3)の語彙は流用しない＝
//   しかる・ほめる・さそう 等は「人に〜される」動詞で、そんけいにすると不自然なため。
//   入れない: できる・わかる・ある（そんけいにしない）／食べる・飲む・見る・いる・寝る（とくべつな ことばを使う）
//   話す・出す等（1Gで「〜されます」になる語）も入れない: ③で3G「されます」を選ぶと答えの形は合っているのに×になるため
// 表記は教科書の表どおり漢字＋ふりがな。漢字{よみ} 記法を R() で <ruby> に展開し、span で包む
//   （.face は flex なので ruby を直下に置くと1文字ずつ縦積みになる）
function R(s){return '<span>'+s.replace(/([一-龥々]+)\{([^}]+)\}/g,'<ruby>$1<rt>$2</rt></ruby>')+'</span>';}
const VERBS=[
  // 1グループ（い段→あ段＋れます）
  {m:R("読{よ}みます"),ba:R("読{よ}まれます"),g:1},
  {m:R("書{か}きます"),ba:R("書{か}かれます"),g:1},
  {m:R("作{つく}ります"),ba:R("作{つく}られます"),g:1},
  {m:R("（写真{しゃしん}を）とります"),ba:R("とられます"),g:1},
  {m:R("帰{かえ}ります"),ba:R("帰{かえ}られます"),g:1,ex:"かえる＝1グループ"},
  {m:R("使{つか}います"),ba:R("使{つか}われます"),g:1,ex:"い→わ"},
  {m:R("会{あ}います"),ba:R("会{あ}われます"),g:1,ex:"い→わ"},
  {m:R("休{やす}みます"),ba:R("休{やす}まれます"),g:1},
  {m:R("待{ま}ちます"),ba:R("待{ま}たれます"),g:1,ex:"ち→た"},
  {m:R("行{い}きます"),ba:R("行{い}かれます"),g:1,ex:"いらっしゃいます も ○"},
  // 2グループ（＋られます）
  {m:R("そだてます"),ba:R("そだてられます"),g:2},
  {m:R("出{で}かけます"),ba:R("出{で}かけられます"),g:2,ex:"うけみ・かのう と おなじ かたち"},
  {m:R("始{はじ}めます"),ba:R("始{はじ}められます"),g:2},
  {m:R("やめます"),ba:R("やめられます"),g:2},
  {m:R("決{き}めます"),ba:R("決{き}められます"),g:2},
  {m:R("考{かんが}えます"),ba:R("考{かんが}えられます"),g:2},
  // 3グループ（します→されます・来ます→来られます）
  {m:R("します"),ba:R("されます"),g:3,ex:"×しられます・なさいます も ○"},
  {m:R("参加{さんか}します"),ba:R("参加{さんか}されます"),g:3},
  {m:R("出張{しゅっちょう}します"),ba:R("出張{しゅっちょう}されます"),g:3},
  {m:R("運転{うんてん}します"),ba:R("運転{うんてん}されます"),g:3},
  {m:R("結婚{けっこん}します"),ba:R("結婚{けっこん}されます"),g:3},
  {m:R("来{き}ます"),ba:R("来{こ}られます"),g:3,ex:"いらっしゃいます も ○"},
  {m:R("持{も}って来{き}ます"),ba:R("持{も}って来{こ}られます"),g:3,ex:"来ます→来られます"}

